// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface AppraisalDueOut {
  employee_id: number;
  full_name: string;
  emp_number: string;
  designation: string;
  department_id: number | null;
  department_name: string | null;
  joined_on: string | null;
  supervisor_id: number | null;
  supervisor_name: string | null;
  last_due: string | null;
  kind: "Probation" | "Annual";
  due_on: string;
  /** A draft already started */
  draft_id: number | null;
  overdue: boolean;
}

export interface AppraisalOut {
  appraisal_id: number;
  appraisal_number: string;
  employee_id: number;
  full_name: string;
  emp_number: string;
  designation: string;
  department_name: string | null;
  kind: "Probation" | "Annual" | "AdHoc";
  reason: string | null;
  incident_id: number | null;
  period_from: string;
  period_to: string;
  /** The scheduled date a probation or annual appraisal answers */
  due_on: string | null;
  appraiser_user_id: number;
  appraiser_name: string;
  ratings: AppraisalRatingOut[];
  targets: string | null;
  overall_rating: "Outstanding" | "Good" | "Satisfactory" | "NeedsImprovement" | "Unsatisfactory" | null;
  strengths: string | null;
  development_needs: string | null;
  development_plan: string | null;
  status: "Draft" | "Signed" | "Acknowledged" | "Cancelled";
  signed_at: string | null;
  sign_stamp: AuthorStampOut | null;
  employee_comments: string | null;
  acknowledged_on: string | null;
  cancel_reason: string | null;
  created_at: string;
  row_version: number;
  /** Signed within appraisal_grace_days of due_on (MSDS HRM 137) */
  on_time: boolean | null;
  /** Training recorded against this appraisal (MSDS HRM 136 ii) */
  trainings_after: number;
}

export interface AppraisalRatingOut {
  criterion: string;
  kind: "Administrative" | "Performance";
  rating: number;
  comment?: string | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface AppraisalIn {
  period_from: string;
  period_to: string;
  /** Default criteria: setting appraisal_criteria (GET /personnel/appraisal-policy/pdf) */
  ratings?: RatingIn[];
  targets?: string | null;
  overall_rating?: "Outstanding" | "Good" | "Satisfactory" | "NeedsImprovement" | "Unsatisfactory" | null;
  strengths?: string | null;
  development_needs?: string | null;
  /** Required below Satisfactory (MSDS HRM 136) */
  development_plan?: string | null;
  employee_id: number;
  kind: "Probation" | "Annual" | "AdHoc";
  /** An ad hoc evaluation: why (an incident, a complaint) */
  reason?: string | null;
  incident_id?: number | null;
  /** Default: you. HR may name the supervisor who will sign (GET /staff/lookup → user_id) */
  appraiser_user_id?: number | null;
}

export interface RatingIn {
  criterion: string;
  kind: "Administrative" | "Performance";
  /** 1 unsatisfactory ... 5 outstanding */
  rating: number;
  comment?: string | null;
}

