/** Appraisals due — GET /api/v1/personnel/appraisals/schedule (who may call: holders of personnel.view or personnel.manage or personnel.appraise). */
export function appraisalSchedule(query?: { days?: number; department_id?: number | null }): Promise<AppraisalDueOut[]> {
  return api<AppraisalDueOut[]>("GET", withQuery(`/personnel/appraisals/schedule`, query), undefined);
}

/** Appraisals — GET /api/v1/personnel/appraisals (who may call: holders of personnel.view or personnel.manage or personnel.appraise). */
export function listAppraisals(query?: { employee_id?: number | null; kind?: "Probation" | "Annual" | "AdHoc" | null; status?: "Draft" | "Signed" | "Acknowledged" | "Cancelled" | null; mine?: boolean; limit?: number }): Promise<AppraisalOut[]> {
  return api<AppraisalOut[]>("GET", withQuery(`/personnel/appraisals`, query), undefined);
}

/** Start an appraisal (draft) — POST /api/v1/personnel/appraisals (who may call: holders of personnel.appraise or personnel.manage). */
export function addAppraisal(body: AppraisalIn): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("POST", `/personnel/appraisals`, body, { idempotent: true });
}

/** One appraisal — GET /api/v1/personnel/appraisals/{appraisal_id} (who may call: personnel.view or personnel.manage, the appraiser and the member of staff appraised). */
export function getAppraisal(appraisal_id: number): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("GET", `/personnel/appraisals/${appraisal_id}`, undefined);
}

/** Write the appraisal — PUT /api/v1/personnel/appraisals/{appraisal_id} (who may call: holders of personnel.appraise or personnel.manage). */
export function updateAppraisal(appraisal_id: number, body: AppraisalUpdateIn): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("PUT", `/personnel/appraisals/${appraisal_id}`, body);
}

/** Sign the appraisal — POST /api/v1/personnel/appraisals/{appraisal_id}/sign (who may call: holders of personnel.appraise). */
export function signAppraisal(appraisal_id: number): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("POST", `/personnel/appraisals/${appraisal_id}/sign`, undefined);
}

/** Cancel a draft appraisal — POST /api/v1/personnel/appraisals/{appraisal_id}/cancel (who may call: holders of personnel.appraise or personnel.manage). */
export function cancelAppraisal(appraisal_id: number, body: AppraisalCancelIn): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("POST", `/personnel/appraisals/${appraisal_id}/cancel`, body);
}

/** The appraisal (PDF) — GET /api/v1/personnel/appraisals/{appraisal_id}/pdf (who may call: personnel.view or personnel.manage, the appraiser and the member of staff appraised). */
export function appraisalPdf(appraisal_id: number): Promise<unknown> {
  return api<unknown>("GET", `/personnel/appraisals/${appraisal_id}/pdf`, undefined);
}

/** The performance appraisal system (PDF) — GET /api/v1/personnel/appraisal-policy/pdf (who may call: any logged-in user). */
export function appraisalPolicy(): Promise<unknown> {
  return api<unknown>("GET", `/personnel/appraisal-policy/pdf`, undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}

/** Appraisals on time; development — GET /api/v1/personnel/appraisals/statistics (who may call: holders of personnel.view or personnel.manage). */
export function appraisalStatistics(query?: { date_from?: string | null; date_to?: string | null }): Promise<AppraisalStatisticsOut> {
  return api<AppraisalStatisticsOut>("GET", withQuery(`/personnel/appraisals/statistics`, query), undefined);
}

/** The member of staff's comments and acknowledgement — POST /api/v1/personnel/appraisals/{appraisal_id}/acknowledge (who may call: the member of staff appraised, or personnel.manage from the signed paper). */
export function acknowledgeAppraisal(appraisal_id: number, body: AppraisalAcknowledgeIn): Promise<AppraisalDetailOut> {
  return api<AppraisalDetailOut>("POST", `/personnel/appraisals/${appraisal_id}/acknowledge`, body);
}

/** Record an individual training — POST /api/v1/personnel/employees/{employee_id}/trainings (who may call: holders of personnel.training.record or personnel.manage). */
export function addTraining(employee_id: number, body: EmployeeTrainingIn): Promise<TrainingRecordOut> {
  return api<TrainingRecordOut>("POST", `/personnel/employees/${employee_id}/trainings`, body, { idempotent: true });
}
